CREATE OR REPLACE FUNCTION public.normalize_currency(c text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path = public AS $$
SELECT CASE WHEN upper(btrim(coalesce(c,''))) IN ('$','US$','USD') THEN 'USD' WHEN upper(btrim(coalesce(c,''))) IN ('€','EUR') THEN 'EUR' WHEN upper(btrim(coalesce(c,''))) IN ('£','GBP') THEN 'GBP' WHEN btrim(coalesce(c,''))='¥' THEN 'JPY' WHEN upper(btrim(coalesce(c,''))) ~ '^[A-Z]{3}$' THEN upper(btrim(c)) ELSE NULL END $$;
UPDATE public.library_extractions SET data = jsonb_set(data,'{currency}',coalesce(to_jsonb(public.normalize_currency(data->>'currency')),'null'::jsonb)) WHERE kind='pricing' AND (data->'currency') IS DISTINCT FROM coalesce(to_jsonb(public.normalize_currency(data->>'currency')),'null'::jsonb);
DROP VIEW public.library_pricing_stats;
CREATE VIEW public.library_pricing_stats AS WITH latest AS(SELECT DISTINCT ON(domain) * FROM public.library_ai_extraction_history WHERE kind='pricing' ORDER BY domain,captured_at DESC,snapshot_id DESC),scoped AS(SELECT l.*,x.sector_group,public.normalize_currency(l.data->>'currency') AS cur FROM latest l CROSS JOIN LATERAL(VALUES('all'::text),(l.sector))x(sector_group)) SELECT sector_group AS sector,count(*) AS sites_extracted,avg((coalesce((data->>'has_free_tier')::boolean,false))::integer)::numeric AS free_tier_share,avg((coalesce((data->>'has_trial')::boolean,false))::integer)::numeric AS trial_share,avg((coalesce((data->>'has_usage_based')::boolean,false))::integer)::numeric AS usage_based_share,avg((coalesce((data->>'has_ai_addon')::boolean,false))::integer)::numeric AS ai_addon_share,avg((coalesce((data->>'ai_credits_model')::boolean,false))::integer)::numeric AS credit_metering_share,percentile_cont(0.5) WITHIN GROUP(ORDER BY (data->>'cheapest_paid_monthly')::numeric) FILTER (WHERE cur='USD') AS median_cheapest_paid_monthly,count(*) FILTER (WHERE cur='USD') AS usd_sites,avg((EXISTS(SELECT 1 FROM jsonb_array_elements(data->'plans') p WHERE (p->>'is_enterprise_contact')::boolean))::integer)::numeric AS enterprise_contact_share FROM scoped GROUP BY sector_group;
GRANT SELECT ON public.library_pricing_stats TO anon,authenticated;
GRANT ALL ON public.library_pricing_stats TO service_role;